Consider a right block $l_t[i..j]$.  As mentioned above, we can assume that when swapping the head $j$ of the block with the  next element to its right, its displacement decreases by $1$. Hence, we have that
\begin{align*}
 \Exp\left[ \left. \phi_{t+1}(j) \, \right| \, \mathcal{F}_t, \mathcal{G}_{t+1} \right] 
 & \leq \left( 1  - \frac{1}{n-1} \right) \cdot \phi_t(j) + \frac{1}{n-1} \cdot \phi_t(j) \cdot e^{-\alpha}  \\
 & = \phi_t(j) \cdot \left( 1  + \frac{1}{n-1} \cdot (e^{-\alpha} - 1) \right)  \\
 & \leq \phi_t(j) \cdot \left( 1  - \frac{\alpha}{2(n-1)} \right),
\end{align*}
using the Taylor estimate $e^{-\alpha} \leq 1 - \alpha/2$ (for any $\alpha \leq 1$).

Further, we can pessimistically assume that the displacement of element $j+1$ increases by $1$. So,
\begin{align}
\Exp\left[ \left. \phi_{t+1}(j+1) \, \right| \, \mathcal{F}_t, \mathcal{G}_{t+1} \right] 
 & \leq \left( 1  - \frac{1}{n-1} \right) \cdot \phi_t(j+1) + \frac{1}{n-1} \cdot \phi_t(j+1) \cdot e^{\alpha} \notag \\
 & = \phi_t(j+1) \cdot \left( 1  + \frac{1}{n-1} \cdot (e^{\alpha} - 1) \right) \notag \\
 & \leq \phi_t(j+1) \cdot \left( 1  + \frac{2\alpha}{n-1} \right), \label{eq:phi_j_plus_one}
\end{align}
using the Taylor estimate $e^{\alpha} \leq 1 + 2\alpha$ (for any $\alpha \leq 1$).

Moreover, in the cases where the displacement of $j$ increases by $1$ (\cref{subfig:right_head_right,subfig:right_head_stationary}), then $\tau_t(l_t[j]) \geq \tau_t(l_t[j-1]) + d$ and so $|d \cdot \tau_t(l_t[j]) - j| \geq |d \cdot \tau_t(l_t[j+1]) - (j+1)| + d-1$. Therefore, we can bound its contribution as follows
\[
\phi_t(j+1) \leq \phi_t(j) \cdot e^{-\alpha (d-1)} \leq \frac{1}{20} \cdot \phi_t(j),
\]
using that $\alpha \cdot (d-1) \geq \log 20$. Returning to~\cref{eq:phi_j_plus_one},
\begin{align} 
 \Ex{ \left. \phi_{t+1}(j+1) \, \right| \, \mathcal{F}_t, \mathcal{G}_{t+1} } 
  & \leq \phi_t(j+1) \cdot \left( 1 - \frac{\alpha}{4(n-1)} \right)
  + \phi_t(j+1) \cdot \frac{9 \alpha}{4(n-1)} \notag \\
  & \leq \phi_t(j+1) \cdot \left( 1 - \frac{\alpha}{4(n-1)} \right)
  + \phi_t(j) \cdot \frac{\alpha}{8(n-1)}. \label{eq:sorting_step_next_element}
\end{align}
Now, for the contribution of the elements of the block~$l_t[i..j]$ we have that

\begin{align}
\Ex{\left. \sum_{\ell = i}^{j} \phi_{t+1}(\ell) \, \right| \, \mathcal{F}_t, \mathcal{G}_{t+1} } 
 &  = \sum_{\ell = i}^{j-1} \phi_t(\ell) +  \phi_t(j) \cdot \left( 1  - \frac{\alpha}{2(n-1)} \right) \notag \\
 &  = \sum_{\ell = i}^{j}  \phi_t(\ell) \cdot \left( 1 - \frac{\alpha}{4(n-1)}  \right) + \sum_{\ell = i}^{j-1}  \phi_t(\ell) \cdot \frac{\alpha}{4 (n-1)}  - \phi_t(j) \cdot \frac{\alpha}{4 (n-1)} \notag \\
 &  \leq \sum_{\ell = i}^{j}  \phi_t(\ell) \cdot \left( 1 - \frac{\alpha}{4 (n-1)} \right) - \phi_t(j) \cdot \frac{\alpha}{8(n-1)}, \label{eq:sorting_step_block}
\end{align}
using in the last inequality that \begin{align*}
\sum_{\ell = i}^{j-1}  \phi_t(\ell) \cdot \frac{\alpha}{4(n-1)} 
  &  \stackrel{(a)}{\leq} \phi_t(j) \cdot \left( \frac{1}{1 - e^{-\alpha (d-1)}}  - 1\right) \cdot \frac{\alpha}{4 (n-1)} \\
  &  = \phi_t(j) \cdot \frac{e^{-\alpha (d-1)}}{1 - e^{-\alpha (d-1)}} \cdot \frac{\alpha}{4 (n-1)} \\
  &  \stackrel{(b)}{\leq} \phi_t(j) \cdot \frac{\alpha}{8 (n-1)},
\end{align*}
where $(a)$ follows by \cref{lem:potential_of_header_dominates} and $(b)$ since $\alpha (d-1) \geq \log 20$.
Therefore, combining \cref{eq:sorting_step_next_element} and \cref{eq:sorting_step_block}, we have that
\begin{align*}
\Ex{ \sum_{\ell = i}^{j+1} \phi_{t+1}(\ell) \, \middle| \, \mathcal{F}_t, \mathcal{G}_{t+1} }
& \leq 
  \sum_{\ell = i}^{j+1}  \phi_t(\ell)\cdot\left( 1 - \frac{\alpha}{4 (n-1)} \right),
\end{align*}
which also implies that
\begin{align*}
\Ex{\sum_{\ell = i}^{j+1} (\phi_{t+1}(\ell) - 1) \, \middle| \, \mathcal{F}_t, \mathcal{G}_{t+1} }
 & \leq  \sum_{\ell = i}^{j+1}  (\phi_t(\ell)  - 1) \cdot \left( 1 - \frac{\alpha}{4 (n-1)} \right).
\end{align*}
Further, by a symmetric argument, for a left block $l_t[i..j]$ we have that
\begin{align*}
\Ex{\sum_{\ell = i - 1}^{j} (\phi_{t+1}(\ell) - 1) \, \middle| \, \mathcal{F}_t, \mathcal{G}_{t+1} } 
 &  \leq \sum_{\ell = i - 1}^{j}  (\phi_t(\ell)  - 1) \cdot \left( 1 - \frac{\alpha}{4 (n-1)} \right).
\end{align*}
By aggregating over all blocks and using that swaps between stationary elements  do not contribute to the potential, we have that
\[
\Ex{\Phi_{t+1} \, \middle| \, \mathcal{F}_t, \mathcal{G}_{t+1} }
  \leq \Phi_t \cdot \left( 1 - \frac{\alpha}{4 (n-1)} \right).
\]
Combining with the fact that deterministically $\Phi_{t+1} \leq \Phi_t$, we conclude that
\[
 \Ex{ \left. \Phi_{t+1} \, \right| \, \mathcal{F}_t} 
   \leq \Phi_t \cdot \left( 1 - \frac{\alpha}{4 (n-1)} \cdot \Ex{\mathbf{1}_{\mathcal{G}_{t+1}} \middle| \mathcal{F}_t} \right). \qedhere
\]
\end{proof}

With the above in mind, we are now ready to prove the main statement:

\begin{proof}
Let $p = \frac{1}{4 \cdot (b+1)}$. We will analyze the process for the last $m = \frac{16d}{p} \cdot n^2$ steps, where $d > 1$ (to be specified below). We will split these steps into $m/(nk)$ groups of $nk$ steps each, where $k = \frac{16^2 \cdot 108 \cdot d^2}{p^2} \cdot \frac{c'}{\lambda^2} \cdot \log n$. At the end of each group of steps we will reset the targets to their original positions, so $\sigma_t = \tau_t = \id_n$. We will consider a \emph{capped process} in which if any of the mixing steps increases the displacement of the target within the current group to more than $M = \frac{1}{\lambda} \sqrt{108 \cdot c' \cdot k \cdot \log n}$, then the current and any future mixing step is not performed. By \cref{lem:mgf_psi_and_target_displacement_bounds}~$(iii)$, we have that
\begin{align}\label{eq:mdev_capped_process_agrees} 
  \Pr\Big[ \bigcap_{t \in [0, m]} \Big\{\max_{i \in [n]} \delta_t(i) \leq M \Big\} \big]
   & \geq 1- n^{-6} \cdot m  \geq 1 - \frac{1}{2n^3},
\end{align}
and so the original process agrees with the capped process at all steps 
with probability at least $1 - \frac{1}{2} n^{-3}$. So, from now on we will be working with the capped process.

Consider the potential $\Phi_t = \Phi_t(\alpha)$ with $\alpha = \frac{\log 20}{d - 1}$. Let $\mathcal{G}_{t+1}$ be the event that step $t+1$ was a sorting step. By \cref{lem:new_sorting_step_drift}, since $\alpha \in [\frac{\log 20}{d - 1}, 1]$, in any step $t$, it holds that
\[
  \Ex{\Phi_{t+1} \, \middle| \, \mathcal{F}_t} \leq \Phi_t \cdot \left( 1 - \frac{\alpha}{4 \cdot (n-1)} \cdot \Ex{\mathbf{1}_{\mathcal{G}_{t+1}} \middle| \mathcal{F}_t } \right).
\]
We denote by $\Phi_{t + nk}'$ the value of the potential before resetting the targets. By aggregating over $nk$ steps, for any step $t$ being the start of a group, we have that
\begin{align}
\Ex{ \Phi_{t+nk}' \, \middle| \, \mathcal{F}_t } 
   & \leq \Phi_t \cdot \prod_{i = 1}^{nk} \left( 1 - \frac{\alpha}{4 (n-1)} \cdot \Ex{\mathbf{1}_{\mathcal{G}_{t+i}} \middle| \mathcal{F}_t} \right) \notag \\ 
   & \leq \Phi_t \cdot e^{-\frac{\alpha}{4(n-1)} \cdot \sum_{i = 1}^{nk} \Ex{\mathbf{1}_{\mathcal{G}_{t+i}} \middle| \mathcal{F}_t}} \notag \\
   & \leq \Phi_t \cdot e^{-\frac{p\alpha}{4} \cdot \frac{nk}{n-1}}, \label{eq:phi_bound_with_reallocation}
\end{align}
where in the last inequality we used that $nk \geq (b+1) \cdot n$ and so by \cref{lem:many_sorting} there is at least a $p$ fraction of sorting steps among the $nk$ steps.

Now, recall that in the capped process, at the end of the~$nk$ steps, the displacement of any single target changes by at most $M$, so each term in the potential increases by at most a factor of $e^{\alpha \cdot d \cdot M}$ plus an additive term of $e^{\alpha \cdot d \cdot M}$. Therefore, \begin{align*}
\Ex{ \Phi_{t+nk} \, \middle| \, \mathcal{F}_t } 
  & \leq \Phi_t \cdot e^{-\frac{p\alpha}{4} \cdot \frac{nk}{n-1} + \alpha \cdot d \cdot M } + n \cdot e^{\alpha \cdot d \cdot M} 
    \leq \Phi_t \cdot e^{-\frac{p\alpha}{8} \cdot k} + n \cdot e^{\alpha \cdot d \cdot M},
\end{align*}
using that $\frac{p\alpha}{8} \cdot k \geq 2\alpha \cdot d \cdot M$ (since $k = \frac{16^2 \cdot 108 \cdot d^2}{p^2} \cdot \frac{c'}{\lambda} \cdot \log n$).

Trivially, at any step, each element is at most $n \cdot d$ units away from their target, so we have that $\Phi_0 \leq n \cdot e^{\alpha \cdot nd}$. By taking the expectation over the $\frac{m}{nk}$ groups we have that 
\begin{align*}
\Ex{ \Phi_{m} } 
   & \stackrel{(a)}{\leq} n \cdot e^{\alpha \cdot nd} \cdot e^{-2\alpha \cdot nd} + n \cdot e^{\alpha \cdot d \cdot M} \cdot \big( 1 + e^{-\frac{p\alpha}{8} \cdot k} + e^{-2 \cdot \frac{p\alpha}{8} \cdot k} + \ldots \big)\\
   & \leq 1 + n \cdot e^{\alpha \cdot d \cdot M} \cdot \frac{1}{1 - e^{-\frac{p\alpha}{8} \cdot k}} \\
   & \stackrel{(b)}{\leq} 2n \cdot e^{\alpha \cdot d \cdot M},
\end{align*}
using in $(a)$ that $\frac{p\alpha}{8} \cdot k \cdot \frac{m}{nk} \geq 2\alpha \cdot nd$ and in $(b)$ that $e^{-\frac{p\alpha}{8} \cdot k} \leq \frac{1}{2}$ (since $k = \omega(1/p)$).

By Markov's inequality we have that \[
  \Pro{\Phi_m \leq 2n^4 \cdot e^{\alpha \cdot d \cdot M}} \geq 1 - n^{-3},
\]
and so we can deduce that
\[
  \Pro{\mdsp(l_m) \leq \frac{1}{\alpha} (\log 2 + 4 \log n) + d \cdot M} \geq 1 - n^{-3}.
\]
Using \cref{lem:dsp_bounds_dev}, we have that for $c = 32 \cdot \frac{16 \cdot 108 \cdot d \cdot c'}{\lambda^2}$
(since $\frac{5}{\alpha} \log n = \frac{20}{\log 20} \log n \leq d \cdot M$) the capped process satisfies,
\[
  \Pro{\mdev(\pi_m) \leq  c \cdot b \cdot \log n} \geq 1 - n^{-3}. 
\]
Finally, by taking the union-bound with \cref{eq:mdev_capped_process_agrees}, the capped process agrees with the original process and so  we conclude that the same bound also holds for the maximum deviation of the original process
\[
  \Pro{\mdev(\pi_m) \leq  c \cdot b \cdot \log n} \geq 1 - \frac{1}{n^3} - \frac{1}{2n^{3}} \geq 1 - n^{-2}.
\]
By setting $d = 2$, we get the conclusion.
\end{proof}
